36: it('should be able to click across browser contexts', async function({ browser }) {
37:   it.info().annotations.push({ type: 'issue', description: 'https://github.com/microsoft/playwright/issues/29096' });
38:   expect(browser.contexts().length).toBe(0);
39: 
40:   const createPage = async () => {
41:     const page = await browser.newPage();
42:     await page.setContent(`<button>Click me</button>`);
43:     await page.locator('button').evaluate(button => {
44:       window['clicks'] = 0;
45:       button.addEventListener('click', () => ++window['clicks'], false);
46:     });
47:     return page;
48:   };
49: 
50:   const clickInPage = async (page, count) => {
51:     for (let i = 0; i < count; ++i)
52:       await page.locator('button').click();
53:   };
54: 
55:   const getClicks = async page => page.evaluate(() => window['clicks']);
56: 
57:   const page1 = await createPage();
58:   const page2 = await createPage();
59: 
60:   const CLICK_COUNT = 20;
61:   await Promise.all([
62:     clickInPage(page1, CLICK_COUNT),
63:     clickInPage(page2, CLICK_COUNT),
64:   ]);
65:   expect(await getClicks(page1)).toBe(CLICK_COUNT);
66:   expect(await getClicks(page2)).toBe(CLICK_COUNT);
67: 
68:   await page1.close();
69:   await page2.close();
70: });

