165: it('should reconnect with credentials after CONNECT 407 closes the socket', {
166:   annotation: { type: 'issue', description: 'https://github.com/microsoft/playwright/issues/40768' }
167: }, async ({ browserType, httpsServer, proxyServer }) => {
168:   // Some HTTP proxies send 407 and close the socket on the first CONNECT, expecting
169:   // the client to reconnect on a new TCP connection with Proxy-Authorization.
170:   httpsServer.setRoute('/target.html', async (req, res) => {
171:     res.end('<html><title>Served by https server via proxy</title></html>');
172:   });
173:   proxyServer.forwardTo(httpsServer.PORT, { allowConnectRequests: true });
174: 
175:   const connectAttempts: { hadAuth: boolean }[] = [];
176:   let closedFirstConnect = false;
177:   proxyServer.setAuthHandler(req => {
178:     // WebKit on Windows uses libcurl and sends Proxy-Authorization preemptively
179:     // on every CONNECT, while libsoup on Linux/macOS sends it only after a 407.
180:     // Force the first CONNECT to fail regardless to deterministically exercise
181:     // the reconnect path on all platforms.
182:     if (req.method !== 'CONNECT' || !req.headers.host?.startsWith('non-existent.com'))
183:       return true;
184:     connectAttempts.push({ hadAuth: !!req.headers['proxy-authorization'] });
185:     if (!closedFirstConnect) {
186:       closedFirstConnect = true;
187:       return false;
188:     }
189:     return !!req.headers['proxy-authorization'];
190:   });
191: 
192:   const browser = await browserType.launch({
193:     proxy: { server: proxyServer.HOST, username: 'user', password: 'secret' },
194:   });
195:   const page = await browser.newPage({ ignoreHTTPSErrors: true });
196:   await page.goto('https://non-existent.com/target.html');
197:   expect(await page.title()).toBe('Served by https server via proxy');
198:   expect(connectAttempts.length).toBeGreaterThanOrEqual(2);
199:   expect(connectAttempts.some(a => a.hadAuth)).toBe(true);

